    if (status == LIBRDP_STATUS_OK)
        status = rdp_session_append_u64_le(buffer, rdp_session_stat_atime(st));
    if (status == LIBRDP_STATUS_OK)
        status = rdp_session_append_u64_le(buffer, rdp_session_stat_mtime(st));
