        rdp_trace_event(RDP_TRACE_CLIENT,
                        event_name,
                        "dvc_channel_id=%u message_id=%u stream_id=%u event_id=%u",
                        session->video_redirection_channel_id,
                        message_id,
                        stream_id,
                        event_id);
